INSERT IGNORE INTO `base_i18n` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3060, 'ja-JP', '<h2>プライバシーポリシー</h2><p>本アプリをご利用いただきありがとうございます。お客様の個人情報を尊重して保護し、アカウントへのログイン、アプリ機能、カスタマーサービスの提供に必要な範囲でのみ取り扱います。</p><h3>1. 情報の利用</h3><p>適用される法令および本ポリシーに従って情報を利用し、関係のない目的には使用しません。</p><h3>2. お客様の権利</h3><p>法令に従って個人情報の確認、訂正、削除を行うか、アプリに掲載された窓口からお問い合わせいただけます。</p>');
INSERT IGNORE INTO `base_i18n` (`target_type`, `target_id`, `locale`, `name`) VALUES (1, 3080, 'ja-JP', '<h2>利用規約</h2><p>本アプリへようこそ。ご利用前に本規約と関連ルールをお読みいただき、内容をご理解ください。アプリサービスを利用することで、本規約に同意したものとみなされます。</p><h3>1. サービスの利用</h3><p>各機能を法令に従い、ページの案内に沿って適切にご利用ください。本アプリを違法行為や他者の権利を侵害する行為に利用してはなりません。</p><h3>2. 規約の変更</h3><p>事業や法令の変更に応じて本規約を更新し、更新内容をアプリ内に表示します。</p>');
